"重跑类确认弹窗(「是否重跑?」等)的等待时长,默认 60 秒:倒计时结束无人答复即自动采用默认选项(通常为「重跑」),流水线不会因等人而卡住。调大可给自己留更多裁决时间,代价是无人值守时流水线在弹窗上等得更久;Agent 显式指定的更短等待仍有效,但不能超过本值。签字类弹窗(H 门人工签字)永不倒计时、永不自动确认,不受本项影响。全局设置,保存后对后续发起的确认生效。": "リトライ系の確認ポップアップ(「再実行しますか?」など)の待ち時間。既定は 60 秒:カウントダウンが終わっても応答がなければ既定の選択肢(通常は「再実行」)を自動採用し、パイプラインが人待ちで止まることはありません。大きくすると判断の時間を長く取れますが、無人時はポップアップでの待機がその分長くなります。Agent が明示したより短い待ち時間は有効ですが、本値を超えることはできません。署名系ポップアップ(H ゲートの人手署名)はカウントダウンせず自動確認もされないため、本設定の影響を受けません。グローバル設定で、保存後に発行される確認から有効になります。",
"⚙️ Agent 高级设置": "⚙️ Agent 詳細設定",
"重跑次数": "リトライ回数",
"Agent 自动重跑/重 roll 的次数上限,默认 0:验收评分、QA 审核或机检不过时,总制片带意见自动退回重做;视频/图像生成机检不达标时自动重 roll。同一任务累计达到该次数仍不过就升级用户裁决,不再自行重试;填 0 则完全不自动重跑,首次不过即升级人工。全局设置,通过运行提示词注入所有 Agent,覆盖流程文档里写死的「最多 3 次」,保存后对后续启动的工单生效。": "Agent が自動で再実行/リロールする回数の上限、既定 0:受入採点・QA 審査・機械チェックに不合格の場合、総合プロデューサーが意見を添えて自動で差し戻してやり直させ、動画/画像生成が機械チェックに不合格なら自動でリロールします。同一タスクがこの回数に達しても不合格ならユーザーの裁定にエスカレーションし、それ以上は自動再試行しません。0 にすると自動再実行を完全に無効化し、初回不合格で即エスカレーションします。グローバル設定で、実行プロンプト経由で全 Agent に注入され、ワークフロー文書に固定記載の「最大 3 回」を上書きします。保存後に起動する工程から有効です。",
"重跑次数需为 0-{max} 的整数(0=不自动重跑)": "リトライ回数は 0〜{max} の整数で入力してください(0=自動再実行なし)",
"轮次上限": "ターン上限",
"单个工单内引擎的对话轮次上限,默认 250:仅对 claude 与 grok 引擎生效(headless 的 --max-turns 参数,不传则不限,这里主动设闸防失控循环);codex/pi/opencode 引擎无此参数不受影响,deepagents 走框架自身的递归上限。撞上限时引擎会被直接切断且无法续跑,回执只显示退出码 1,已落盘的产物保留但核验与回执缺失——大批量工位(逐组选片、批量切片)一单几十组时 100 轮远远不够,如仍撞限优先调小派单批宽、其次上调本值。全局设置,保存后对后续启动的工单生效。": "1 つの作業指示内でのエンジン対話ターン数の上限、既定値 250:claude と grok エンジンにのみ有効(headless の --max-turns パラメータ。未指定なら無制限のため、暴走ループ防止として敢えて上限を設定)。codex/pi/opencode エンジンには該当パラメータがなく影響なし。deepagents はフレームワーク自身の再帰上限を使用。上限到達時はエンジンが即座に切断され再開不可 — 受領書には終了コード 1 のみが表示され、保存済み成果物は残るが検証と受領書が欠落する。大量処理の工程(グループごとの選定、バッチ切り出し)では 1 件で数十グループを扱うため 100 ターンでは全く足りない。上限に達する場合はまず配車バッチ幅を小さくし、次に本値を引き上げること。グローバル設定。保存後に開始する作業指示から有効。",
"轮次上限需为 {min}-{max} 的整数": "ターン上限は {min}〜{max} の整数で指定してください",
"思考深度": "思考深度",
"引擎默认": "エンジン既定",
"思考深度(Thinking Effort)统一设置,默认「引擎默认」:派单时按当前引擎翻译成各自的推理强度参数——claude → --effort,codex → model_reasoning_effort(无 max,按 xhigh),pi → --thinking,opencode → --variant(模型没有该档位时被忽略),grok → --reasoning-effort(无 max,按 xhigh),deepagents → reasoning_effort(仅云端/OpenRouter 渠道,本地模型不传);kimi CLI 无对应参数,不受影响。越深越稳但越慢、token 消耗越高;「引擎默认」不传任何参数,沿用各引擎自身配置(如 ~/.claude/settings.json 的 effortLevel、~/.codex/config.toml 的 model_reasoning_effort)。全局设置,对所有 Agent 生效,保存后对后续启动的工单生效。": "思考深度(Thinking Effort)の統一設定、既定は「エンジン既定」:派遣時に現在のエンジンごとの推論強度パラメータへ変換します——claude → --effort、codex → model_reasoning_effort(max なし、xhigh に対応)、pi → --thinking、opencode → --variant(モデルにその段階がなければ無視)、grok → --reasoning-effort(max なし、xhigh に対応)、deepagents → reasoning_effort(クラウド/OpenRouter チャネルのみ、ローカルモデルには送らない);kimi CLI には該当パラメータがなく影響なし。深いほど安定しますが遅く、token 消費が増えます。「エンジン既定」は何も渡さず各エンジン自身の設定(~/.claude/settings.json の effortLevel、~/.codex/config.toml の model_reasoning_effort など)に従います。全体設定で全 Agent に適用、保存後に起動するジョブから有効。",
