"——与主画幅不同画幅的平台(如主画幅选 16:9 时的 TikTok/抖音)在发布期由 platform-adapter 从母版裁切适配,不重新生成视频;语言约束剧本/台词/旁白/字幕/配音/发布物料(给生成模型的英文 prompt 不受影响);草稿分辨率用于迭代/待审版本,成片分辨率是审核确认后终稿的目标分辨率——与草稿档不同时默认由超分(upscale)得到,不重新生成;分辨率越高视频生成费用越高(4K 仅 Seedance 2.0 标准版支持)。": "——メインのアスペクト比と異なるプラットフォーム(例:メインが 16:9 のときの TikTok/Douyin)は、公開段階で platform-adapter がマスター版からクロップして適応し、動画は再生成しません。言語は脚本/セリフ/ナレーション/字幕/ボイスオーバー/公開素材を制約します(生成モデルに渡す英語 prompt には影響しません)。ドラフト解像度はイテレーション/レビュー待ち版に使用します。最終カット解像度はレビュー確定後の最終版の目標解像度で——ドラフトと異なる場合はデフォルトでアップスケール(upscale)により得られ、再生成はしません。解像度が高いほど動画生成コストは高くなります(4K は Seedance 2.0 標準版のみ対応)。",
