"参考素材保存在项目 refs/ 目录,视觉/配乐 Agent 工作前必查、优先参考。给每个文件添加注释(哪张图管什么、哪首曲子想用在哪)会写入 refs/NOTES.md,相关 Agent 必读并按注释执行。也可拖拽文件到分类区域直接上传。": "参考素材はプロジェクトの refs/ ディレクトリに保存され、ビジュアル/音楽 Agent は作業前に必ず確認し優先的に参考にします。各ファイルの注釈(どの画像が何を決めるか、どの曲をどこで使いたいか)は refs/NOTES.md に書き込まれ、関連 Agent は必読・注釈どおりに実行します。カテゴリ領域へのドラッグ&ドロップでもアップロードできます。",
