"官方云端执行,无需本地部署;API Key 在": "公式クラウドで実行(ローカル展開不要)。API Key は",
"创建(需 Comfy Cloud 订阅,与网页版共用月度额度,免费档无 API 权限);工作流下拉与本地一致(须为 API 格式);依赖自定义节点的工作流(如 ACE-Step/IndexTTS-2/MiniMax-H3)在云端可能不可用,以「测试连接」结果为准": "で作成(Comfy Cloud サブスクリプションが必要。月間クレジットは Web 版と共用、無料プランは API 利用不可)。ワークフローのプルダウンはローカルと同じ(API 形式必須)。カスタムノード依存のワークフロー(ACE-Step/IndexTTS-2/MiniMax-H3 など)はクラウドでは使えない場合があります。「テスト接続」の結果をご確認ください",
