"云端模型": "クラウドモデル",
"所有 OpenAI 兼容 API 均可使用(默认 DeepSeek 官方端点):换 Base URL / API Key / 模型 ID 即可接入其他服务商;「测试连接」会列出端点上可用的模型": "OpenAI 互換 API はすべて利用可能(デフォルトは DeepSeek 公式エンドポイント)。Base URL / API Key / モデル ID を変えれば他社サービスにも接続できます。「接続テスト」でエンドポイント上の利用可能なモデルを一覧表示します",
"sk-…(DeepSeek 开放平台创建;其他 OpenAI 兼容服务商 Key 亦可)": "sk-…(DeepSeek オープンプラットフォームで作成。他の OpenAI 互換サービスの Key も可)",
"本集标题": "エピソードタイトル",
"材质": "マテリアル",
"构想与风格保存在项目的 brief.md,注入该项目每个 Agent 的系统提示词,作为最高创作前提;画面风格约束全部画面视觉产出。保存后对之后派发的任务生效;全部清空保存则移除该设定。叙事节奏改在「视频节奏」设置中配置": "構想とスタイルはプロジェクトの brief.md に保存され、各 Agent のシステムプロンプトに最優先の創作前提として注入されます。画面スタイルはすべての映像出力を制約します。保存後に派遣されるタスクから有効。すべて空で保存すると設定を削除。叙事リズムは「映像リズム」で設定します",
"叙事节奏保存在项目的 brief.md 并注入每个 Agent 的系统提示词,节拍链约束剧本分集/分场与分镜节拍": "叙事リズムはプロジェクトの brief.md に保存され各 Agent のシステムプロンプトに注入されます。ビートチェーンが脚本のエピソード/シーン分割と絵コンテのテンポを制約します",
