"此处配置「本地模型」渠道:OpenAI 兼容端点均可(LM Studio / Ollama / vLLM…)。LM Studio 先": "ここでは「ローカルモデル」プロバイダーを設定します:OpenAI 互換エンドポイントなら何でも使えます(LM Studio / Ollama / vLLM…)。LM Studio はまず",
"此操作不可恢复:产物、运行记录将一并删除。删除后自动跳转到第一个项目。": "この操作は元に戻せません:成果物、実行記録がまとめて削除されます。削除後は自動的に最初のプロジェクトへ移動します。",
