"每集时长决定剧本分集(episode_plan 每集预算);分镜时长范围约束 storyboard / shot-planning 的每镜设计": "エピソードの長さは脚本のエピソード分割(episode_plan の各話バジェット)を決めます。ショット長の範囲は storyboard / shot-planning の各ショット設計を制約します",
"每集时长决定剧本分集(episode_plan 每集预算);分镜时长范围约束 storyboard / shot-planning 的每镜设计。": "エピソードの長さは脚本のエピソード分割(episode_plan の各話バジェット)を決めます。ショット長の範囲は storyboard / shot-planning の各ショット設計を制約します。",
"每集时长需大于 0": "エピソードの長さは 0 より大きい値にしてください",
