"父级:": "親:",
"片头制作要求(留空按团队默认),可输入:\n- 时长上限(如 ≤10s)\n- 剧名:显示用标题/副标题(比如加英文名)\n- 厂标/Logo 图路径(可选,指向 refs/ 下的文件)": "オープニング制作要件(空欄ならチームのデフォルト)。入力例:\n- 長さ上限(例: ≤10s)\n- 作品名:表示用タイトル/サブタイトル(英語名の併記など)\n- スタジオロゴ/Logo 画像パス(任意、refs/ 配下のファイルを指定)",
"片尾制作要求(留空按团队默认),可输入:\n- 时长上限(如 ≤15s)\n- 制作署名:公司名、网站 URL\n- 版权声明模板:如 © {year} {公司名}\n- 社媒/二维码(可选,指向 refs/ 下的文件)\n- 合集信息显示": "エンディング制作要件(空欄ならチームのデフォルト)。入力例:\n- 長さ上限(例: ≤15s)\n- 制作クレジット:会社名、サイト URL\n- 著作権表記テンプレート:例 © {year} {公司名}\n- SNS/QR コード(任意、refs/ 配下のファイルを指定)\n- シリーズ情報の表示",
