"生成;更新的模型可选「自定义…」填 Model ID,也可填「推理接入点 ep-…」": "で生成します。新しいモデルは「カスタム…」を選んで Model ID を入力するか、「推論エンドポイント ep-…」を入力することもできます",
"生成;模型 ID 也可填「推理接入点 ep-…」": "で生成します。モデル ID には「推論エンドポイント ep-…」も入力できます",
"生成模型": "生成モデル",
"生成模型设置 — Agentics：VideoAgents": "生成モデル設定 — Agentics: VideoAgents",
"生成组 {ep}/{gid}(镜 {range}{sc};数据 directing/{ep}/shot_list.json 中 generation_groups group_id={gid},组视频 prompt assets/prompts/{ep}/{gid}.json,组视频 assets/clips/{ep}/{gid}.mp4)": "生成グループ {ep}/{gid}(ショット {range}{sc}。データは directing/{ep}/shot_list.json の generation_groups group_id={gid}、グループ動画 prompt は assets/prompts/{ep}/{gid}.json、グループ動画は assets/clips/{ep}/{gid}.mp4)",
"生效渠道=当前选中的标签页(✅),保存后生效;各渠道配置可同时保存": "有効プロバイダー=現在選択中のタブ(✅)。保存後に有効になります。各プロバイダーの設定は同時に保存できます",
"生物资产": "クリーチャーアセット",
"画布还是空的": "キャンバスはまだ空です",
"画幅约束分镜构图/关键帧/视频/成片,发布平台只决定发布阶段的平台清单(不同画幅平台由发布期裁切适配);语言约束剧本/台词/旁白/字幕/配音;草稿分辨率用于迭代/待审版本,成片终稿由超分得到,分辨率越高视频生成费用越高": "アスペクト比はショット構図/キーフレーム/動画/最終カットを制約します。公開プラットフォームは公開段階のプラットフォーム一覧のみを決めます(異なるアスペクト比のプラットフォームは公開時にクロップで適応)。言語は脚本/セリフ/ナレーション/字幕/ボイスオーバーを制約します。ドラフト解像度はイテレーション/レビュー待ち版に使用し、最終カットはアップスケールで得られます。解像度が高いほど動画生成コストは高くなります",
"画幅约束画幅规范/分镜构图/关键帧/视频/成片;发布平台(可多选)只决定发布阶段发到哪些平台及封面/字幕/画幅矩阵的平台清单,": "アスペクト比はアスペクト比規範/ショット構図/キーフレーム/動画/最終カットを制約します。公開プラットフォーム(複数選択可)は、公開段階でどのプラットフォームに配信するか、およびサムネイル/字幕/アスペクト比マトリクスのプラットフォーム一覧のみを決めます。",
"界面与 agent 对话语言(全局设置;首次打开按浏览器语言自动判断)": "UI と agent の対話言語(グローバル設定。初回はブラウザ言語で自動判定)",
"的全部文件。": "の全ファイル。",
"的整个目录(全部产物、运行记录),": "のディレクトリ全体(全成果物、実行記録)が削除され、",
"确定": "OK",
"确认删除": "削除を確認",
"禁用的段落不制作、不占时长额度;要求文本注入片头片尾(title)/剪辑(edit)/钩子(hook)与总制片的系统提示词,优先级高于 SOUL.md 默认方案": "無効化したセクションは制作されず、時間の割り当ても消費しません。要件テキストはオープニング・エンディング(title)/編集(edit)/フック(hook)とプロデューサーのシステムプロンプトに注入され、SOUL.md のデフォルト案より優先されます",
