",自动运行每次唤醒总制片时都随消息附带,总制片会话重开也不丢失;适合放长期约束,建议写成条件式(如「在 ep01-ep10 剧本全部完成前,不派设定类工单」),留空则不附带": "、自動実行が総合プロデューサーを起こすたびにメッセージへ添付され、セッションが再開されても失われません。長期的な制約の記載に適し、条件式での記述を推奨(例:「ep01-ep10 の脚本がすべて完成するまで、設定系の作業指示を発行しない」)。空欄なら添付しません",
