"Voice Design 模型按角色嗓音的文字描述生成嗓音样本(人物嗓音设计时用),Voice Clone 模型按嗓音样本 + 对白文字生成对白": "Voice Design モデルはキャラクターの声の文章説明から声サンプルを生成し(声の設計時)、Voice Clone モデルは声サンプル+台詞テキストから台詞音声を生成します",
"Voice Design:按角色嗓音的文字描述生成嗓音样本(人物嗓音设计时用);Voice Clone:按嗓音样本 + 对白文字生成对白。两者按用途自动选择;未配置 Voice Design 时一律走 Voice Clone": "Voice Design:キャラクターの声の文章説明から声サンプルを生成(キャラクターの声を設計するとき)。Voice Clone:声サンプル+台詞テキストから台詞音声を生成。用途に応じて自動で選択され、Voice Design 未設定時はすべて Voice Clone を使います",
