"获取;工作流须先在网页端跑通,并把 {{PROMPT}} 等占位符写入对应节点输入位(约定与本地工作流一致),再把工作流 ID 或页面链接粘贴到「添加工作流」验证;国内站与国际站账号与 Key 不互通": "で取得。ワークフローは先にウェブ側で正常に実行できることを確認し、{{PROMPT}} などのプレースホルダーを対応するノードの入力スロットに書き込んだうえで(ローカルワークフローと同じ約束事)、ワークフロー ID またはページリンクを「ワークフローを追加」に貼り付けて検証してください。中国版サイトと国際版サイトのアカウントと Key は相互に利用できません",
"API 服务页": "API サービスページ",
"待提交问题": "提出待ちの問題",
"🐞 待提交问题": "🐞 提出待ちの問題",
"待提交问题:Agent 运行中发现系统代码缺陷或需要新增功能时自动整理成 issue,点击查看并提交给开发者,让你的客户端运行得更好": "提出待ちの問題:Agent が実行中にアプリコードの欠陥や必要な新機能を見つけると自動的に issue にまとめます。クリックして確認し開発者に提出すると、クライアントの動作改善につながります",
"Agent 运行中确认问题属于系统代码缺陷、或需要系统新增功能时,自动整理成 issue 列在下方,点「提交」即打开预填好的 GitHub 页面由你确认提交。": "Agent が実行中に、問題がアプリコードの欠陥である、またはアプリに新機能が必要だと確認した場合、自動的に issue にまとめて下に一覧表示します。「提出」を押すと入力済みの GitHub ページが開き、確認して提出できます。",
"问题只写机制,内容已脱敏(路径、项目名、密钥),不含剧情、提示词与项目内容。": "問題は仕組みのみを記述し、内容はマスキング済み(パス・プロジェクト名・キー)です。ストーリー、プロンプト、プロジェクト内容は含みません。",
