"默认关。开启后控制台每个 Agent 面板显示「SOUL.md」按钮,可查看该 Agent 的身份原文;关闭时若正在看 SOUL.md 原文会自动退回对话。全局设置,保存后立即生效,不影响任何 Agent 的运行。": "既定はオフ。オンにするとコンソールの各 Agent パネルに「SOUL.md」ボタンが表示され、その Agent のアイデンティティ原文を確認できます。SOUL.md 表示中にオフにすると会話に戻ります。グローバル設定で、保存後すぐに反映され、Agent の実行には影響しません。",
