"火山方舟私域虚拟人像素材库:人物形象图入库后,生成视频时自动以资产 URI 提交,规避人脸参考图审核拦截": "Volcano Ark プライベート人物素材ライブラリ:キャラクター画像を登録すると、動画生成時に自動でアセット URI として送信され、顔参照画像の審査ブロックを回避できます",
"🧑‍🎨 虚拟人像资产库": "🧑‍🎨 バーチャル人物素材ライブラリ",
"火山方舟私域素材库:入库的人物形象图在生成视频时以资产 URI 提交,规避人脸参考图审核拦截": "Volcano Ark プライベート素材ライブラリ:登録済みキャラクター画像は動画生成時にアセット URI で送信され、顔参照画像の審査ブロックを回避します",
"📋 使用前准备": "📋 事前準備",
"在火山方舟开通": "Volcano Ark で",
"高级创作权益包": "高度創作特典パッケージを開通",
"(私域虚拟人像素材库的前置条件)。": "(プライベート人物素材ライブラリの前提条件)。",
"在火山引擎控制台": "Volcano Engine コンソールの",
"API 访问密钥管理": "API アクセスキー管理で",
"创建并获取 Access Key / Secret Key(IAM 密钥,非 ark- 开头的方舟 API Key),填入下方并保存。": "Access Key / Secret Key(IAM キー。ark- で始まる方舟 API Key ではありません)を作成・取得し、下欄に入力して保存します。",
"点击「启用」后,可在下方管理已入库的素材;人物预览页每张形象图会出现「入库」按钮,分镜重出时已入库(Active)的参考图自动以资产 URI(asset://素材ID)提交。": "「有効化」をクリック後、下で登録済み素材を管理できます。キャラクタープレビューの各画像に「登録」ボタンが表示され、グループ再出力時に登録済み(Active)の参照画像は自動的にアセット URI(asset://素材ID)で送信されます。",
"注意:上传入库为异步审核(Processing → Active/Failed),仅 Active 状态的素材可用于视频生成;素材按方舟「项目」隔离,下方 ProjectName 须与「生成模型」页视频生成所用方舟 API Key 所属项目一致(默认 default)。": "注意:登録は非同期審査です(Processing → Active/Failed)。Active 状態の素材のみ動画生成に使用できます。素材は方舟の「プロジェクト」で分離されるため、下の ProjectName は「生成モデル」ページの動画生成用方舟 API Key の所属プロジェクトと一致させてください(既定 default)。",
"🔑 密钥与开关": "🔑 キーと有効化",
"Access Key / Secret Key 留空时,自动使用「⚙️ 设置 → 文件托管 → 火山引擎 TOS」已配置的 AK/SK(或环境变量 TOS_ACCESS_KEY/TOS_SECRET_KEY)。": "Access Key / Secret Key を空にすると、「⚙️ 設定 → ファイルホスティング → Volcano TOS」に設定済みの AK/SK(または環境変数 TOS_ACCESS_KEY/TOS_SECRET_KEY)を自動使用します。",
"default(须与视频生成 API Key 所属项目一致)": "default(動画生成 API Key の所属プロジェクトと一致させること)",
"文件托管自检:": "ファイルホスティング自己診断:",
