"HunyuanImage 3.0(Fal 托管;仅文生图,支持负面提示词)": "HunyuanImage 3.0(Fal ホスト;テキストから画像のみ、ネガティブプロンプト対応)",
"Fal 图像生成 API(queue.fal.run 异步队列,托管 Seedream、Nano Banana、GPT Image、FLUX.2、Qwen Image 等端点);模型 ID 填家族前缀,无参考图走文生图端点、有参考图自动切 edit 端点,「自定义…」也可填完整端点 ID;尺寸/参考图上限/seed 按模型映射;Key 与视频段 Fal 共用(任一处填写即可),在": "Fal 画像生成 API(queue.fal.run 非同期キュー。Seedream、Nano Banana、GPT Image、FLUX.2、Qwen Image などのエンドポイントをホスト)。モデル ID はファミリー接頭辞で、参照なしはテキストから画像、参照ありは自動で edit エンドポイントに切替。「カスタム…」で完全なエンドポイント ID も指定可。サイズ/参照上限/seed はモデルごとにマッピング。Key は動画 → Fal タブと共用(どちらか一方で可)、作成は",
