"Kling 3.0 Pro(Fal 托管;首尾帧,3-15 秒,原生音频,不支持参考素材)": "Kling 3.0 Pro(Fal ホスト;先頭/末尾フレーム、3–15 秒、ネイティブ音声、参照素材非対応)",
"Kling 3.0 Standard(Fal 托管;首尾帧,3-15 秒,原生音频,不支持参考素材)": "Kling 3.0 Standard(Fal ホスト;先頭/末尾フレーム、3–15 秒、ネイティブ音声、参照素材非対応)",
"Fal 视频生成 API(queue.fal.run 异步队列,托管 Seedance 2.0/2.5、MiniMax H3、Kling 3.0、Wan 3.0 等端点);模型 ID 填家族前缀,按输入自动补 text-to-video / image-to-video / reference-to-video 任务段,「自定义…」也可填完整端点 ID;分辨率/时长/参考素材上限随所选模型(与官方渠道同口径);Key 在": "Fal 動画生成 API(queue.fal.run 非同期キュー。Seedance 2.0/2.5、MiniMax H3、Kling 3.0、Wan 3.0 などのエンドポイントをホスト)。モデル ID はファミリー接頭辞で、入力に応じて text-to-video / image-to-video / reference-to-video のタスク部分を自動付加。「カスタム…」で完全なエンドポイント ID も指定可。解像度/長さ/参照上限は選択モデルに従う(公式チャネルと同じ基準)。Key は",
