"播放策略:按顺序播放已生成的片段;新片段还没到时重播最新一段,到了就在当前段结束后接上,不会打断正在播的画面。生成通常慢于播放,所以\"回放\"是常态——把单段时长调长可以减少重播占比。待播片段达到上限(默认 3 段,高级选项可调)时暂停生成,播掉一段再继续。停止后循环回放全部片段。": "再生方針:生成済みクリップを順に再生。次のクリップが未着なら最新クリップを再再生し、届いたら現在のクリップ終了後につなぎ、再生中の映像は中断しません。生成は通常再生より遅いため「再再生」が常態です。クリップ長を伸ばすと再再生の割合が減ります。未再生が上限(デフォルト 3 本、詳細オプションで変更可)に達すると生成を一時停止し、1 本再生すると再開。停止後は全クリップをループ再生。",
