"{shot}: 运镜 {move} 需白模计划提供数值关键帧，暂按固定机位显示。": "{shot}: カメラ動作 {move} には計画内の数値キーフレームが必要です。現在は固定カメラで表示しています。",
"{shot}: 运镜幅度由 {move} 推断，请校准数值轨迹。": "{shot}: カメラの移動量を {move} から推定しています。数値軌道を較正してください。",
