"本组 prompt 的 video_refs:随重出本组时按序作为参考视频(--ref-video)传给视频生成模型,正文以 [Video N] 引用(编号=列表序号)。白模/前组尾段视频由流水线注入,本地上传的视频须在重出 prompt 时补写 [Video N] 说明句。": "このグループの prompt の video_refs:グループ再生成時に順番どおり参照動画(--ref-video)として動画モデルへ渡され、本文では [Video N](N=リスト番号)で参照します。ホワイトボックス/前グループ末尾の動画はパイプラインが注入し、ローカルアップロードの動画は prompt 再生成時に [Video N] の説明文を追記する必要があります。",
