"⚠ {reason}。视频生成模型会拒绝提交,请二选一:① 在下方删除多余/过长的参考视频;② 点「🎛 模型」给本组单独换参考视频上限更高的视频模型(如 Seedance 2.5:≤10 个/总时长 ≤30s,渠道不变)。处理后重出本组。": "⚠ {reason}。動画モデルは送信を拒否します。次のいずれかを選択:① 下で余分/長すぎる参照動画を削除;② 「🎛 モデル」でこのグループだけ参照動画上限の高いモデルに変更(例:Seedance 2.5:10本以下/合計30s以下、プロバイダーは同じ)。対応後にグループを再生成してください。",
