"插黑 / 定格": "黒 / 停止",
"把选中的时间段直接删掉,剩下的内容按原顺序拼成本组新版本(时长变短,出成片时外挂声轨/字幕按时间映射表自动同步)": "選択した時間帯をそのまま削除し、残りを元の順序でつないでこのグループの新バージョンにします(尺が短くなります。完成時に外部音声と字幕はタイムマップで自動同期)",
"控制切换节奏:在当前时刻插入「前一帧定格 + 黑场」生成本组新版本;或放在本组开头 / 结尾的组边界,写成组间转场处方(提交即回写 shot_list,出成片时插帧)。成片按插入量变长,外挂声轨与字幕按同一张时间映射表自动平移;黑场声音可延续前段、淡出或静音": "切り替えのテンポ制御:再生位置に「前フレームの停止 + 黒」を挿入して新バージョンを作るか、グループの先頭 / 末尾の境界に置いてグループ間トランジションの処方として書き込みます(提出で shot_list に反映、完成時にフレーム挿入)。挿入分だけ本編が長くなり、外部音声と字幕は同じタイムマップで自動シフト。黒の間の音は継続 / フェード / 無音を選べます",
"分镜剪辑,四个模块:① 删段——选中的时间段直接删除,剩余拼成新版本;② 换段——切掉的时间段用本组另一版本同段替代;③ 插黑 / 定格——在当前时刻或组边界插入定格帧 + 黑场控制切换节奏;④ 派单剪辑师——输入指令发给剪辑师工位,产物登记为新版本": "ショット編集の 4 モジュール:① 削除 — 選択区間を削除し残りで新バージョン;② 差し替え — 切った区間を同グループ別バージョンの同区間に;③ 黒 / 停止 — 再生位置または境界に停止フレーム + 黒を挿入してテンポを制御;④ 編集者へ依頼 — 指示を編集エージェントへ送り、成果物を新バージョンとして登録",
