"默认勾选:白模调度 Agent 每次新建或修改分镜白模、编译通过后,用宿主命令 render_whitebox.py --stills 对本单改动过的组做无头渲染——每镜取首/中/尾等时刻的摄影机视角加一张空间视角,拼成每组一张联系表(项目 directing 下该集的 whitebox/stills 目录),Agent 读图核对主体是否在画内、有无被墙或道具遮挡、正面/背影与调度是否一致、景别是否相符,有问题先自行修正或开待决项,再交你在预览页审看签字。渲染全在本机完成,不调用任何生成模型、不产生费用,也不导出 camera.mp4(导出仍须 H3W 签字);每组约多花十几秒与一次读图的 token。取消勾选则只做数值自检与宿主机检,不出静帧。全局设置,通过运行提示词注入白模调度 Agent,保存后对后续启动的工单生效。": "既定でオン:ホワイトボックス調度 Agent が絵コンテのホワイトボックスを新規作成・修正してコンパイルが通るたびに、ホストコマンド render_whitebox.py --stills でその作業で変更したグループをヘッドレス描画します。各ショットの開始/中間/終了などの時点のカメラ視点と空間視点 1 枚を、グループごとに 1 枚のコンタクトシート(プロジェクト directing 配下の該当話 whitebox/stills フォルダ)にまとめ、Agent が画像を読んで被写体がフレーム内か、壁や小道具に遮られていないか、正面/背面が演出と一致するか、ショットサイズが合っているかを確認し、問題があれば自分で修正するか保留項目を起票してから、プレビューページでの確認・署名に回します。描画はすべてローカルで行われ、生成モデルは呼ばず費用も発生せず、camera.mp4 も書き出しません(書き出しには引き続き H3W 署名が必要)。グループごとに十数秒と画像 1 回分のトークンが追加でかかります。オフにすると数値の自己点検とホスト機械チェックのみで、静止フレームは出しません。グローバル設定で、実行プロンプト経由でホワイトボックス調度 Agent に注入され、保存後に開始する作業から有効です。",
"本组尚未白模调度，当前没有可审看的白模。": "このグループはまだホワイトボックス演出が行われておらず、確認できるホワイトボックスはありません。",
"白模调度 Agent 完成本集工单后这里会显示正式白模；在此之前无需对白模提修改意见。": "ホワイトボックス演出 Agent が本話の作業指示を完了すると、ここに正式なホワイトボックスが表示されます。それまではホワイトボックスへの修正依頼は不要です。",
"系统按分镜与动线自动推断的粗略白模，机位、走位、朝向多为估计值，不是白模调度的交付物": "絵コンテと動線からシステムが自動推定した粗いホワイトボックスです。カメラ位置・移動・向きの多くは推定値で、ホワイトボックス演出の成果物ではありません",
