"手机扫码手绘构图线稿;勾选「AI 加工」(默认)结合已有参考图按项目风格生成最终参考图,不勾选则手绘原图直接加入本组": "スマホでQRを読み取り構図ラフを手描き。「AI加工」オン(既定)なら既存の参考画像とプロジェクトのスタイルで最終参考画像を生成、オフなら原画をそのままこのグループに追加します",
"手机扫码打开画布(同一局域网);画构图线稿并配文字说明,提交后结合本组已有参考图与项目风格生成最终参考图,自动加入本组;画布页取消勾选「AI 加工」则手绘原图直接加入本组": "スマホでQRを読み取りキャンバスを開く(同一LAN);構図ラフを描いて説明文を添えて送信すると、このグループの既存参考画像とプロジェクトのスタイルで最終参考画像を生成し自動で追加します。キャンバスページで「AI加工」をオフにすると原画をそのまま追加します",
