"手机扫码打开画布(同一局域网);画好提交后由 AI 按分镜草图风格重绘作为该分镜的草图;画布页取消勾选「AI 加工」则手绘原图直接作为草图": "スマホでQRを読み取りキャンバスを開く(同一LAN);送信した絵はAIが絵コンテスケッチ風に描き直してこのカットのスケッチになります。キャンバスページで「AI加工」をオフにすると原画がそのままスケッチになります",
"手机扫码画一张草图;默认由 AI 按分镜草图风格重绘,画布页取消勾选「AI 加工」则原图直接作为这一镜的草图": "スマホでQRを読み取ってスケッチを描きます。既定ではAIが絵コンテスケッチ風に描き直し、キャンバスページで「AI加工」をオフにすると原画がそのままこのカットのスケッチになります",
