"MiniMax H3 Max Lip Sync(Fal 托管;对口型:1 张人物图 + 1 段 5–14.8 秒音频,无提示词,成片时长随音频,480P/768P/1080P/2K)": "MiniMax H3 Max Lip Sync(Fal ホスト;リップシンク:人物画像 1 枚 + 5–14.8 秒の音声 1 本、プロンプトなし、尺は音声に従う、480P/768P/1080P/2K)",
"MiniMax H3 Max Lip Sync:每段都用第 1 张参考图作人物图(画面不漂,但段与段之间会跳);画幅随图片": "MiniMax H3 Max Lip Sync:毎回参照 #1 を人物画像に使用(画面は崩れないがクリップ間で飛ぶ);アスペクト比は画像に従い",
"MiniMax H3 Max Lip Sync:首轮用第 1 张参考图作人物图,之后每轮用上一段尾帧(衔接模式选「不衔接」则每段都用第 1 张参考图);画幅随图片": "MiniMax H3 Max Lip Sync:1 巡目は参照 #1 を人物画像に、以降は前クリップの末尾フレームを使用(連結モード「連結しない」なら毎回参照 #1);アスペクト比は画像に従い",
"对口型模型需要至少 1 张参考图(第 1 张作为人物图)": "リップシンクモデルには参照画像が 1 枚以上必要です(1 枚目が人物画像)",
