"人物要说的话;按句分段,逐段语音合成后驱动口型": "人物が話す内容。文ごとに区切り、区間ごとに音声合成してから口の動きを駆動します",
"例如:大家好,欢迎来到我的直播间!今天想和大家聊一聊最近在看的一本书。": "例:みなさんこんにちは、配信へようこそ!今日は最近読んでいる本についてお話しします。",
"语音用「生成模型」页当前的 TTS 配置与默认音色合成({tts})。台词念完不会停播,会等你更新台词:在原文后面追加的部分接着念,整段改写则从头念新台词。": "音声は「生成モデル」ページの現在の TTS 設定と既定の音色で合成します({tts})。セリフを読み終えても配信は止まらず、更新を待ちます:原文の後ろに追記した分は続けて読み、全体を書き換えた場合は新しいセリフを最初から読みます。",
"对口型:台词按句打包成每段约该秒数({lo}–{hi} 秒)的小段;每段成片时长 = 该段语音时长(不足 5 秒补静音)": "リップシンク:セリフを文単位でおよそこの秒数({lo}–{hi} 秒)の区間にまとめます。各クリップの尺 = その区間の音声の長さ(5 秒未満は無音で補完)",
