"背景图模式": "背景プレートモード",
"白模开启时分镜背景图的参考来源(全局设置,场景预览页可按场景覆盖)。九宫格:每个场景按布局包里的九个机位、以俯视图为参考一次生成一张 3×3 宫格,拆成 9 张背景图入库,每镜按白模机位自动选最合适的一格;选不到合适的(朝向/俯仰/距离/机高超限)自动以俯视图+九宫格整图为参考按本镜机位补出一张。": "白モデル有効時のショット背景図の参照元(全体設定。シーンプレビューページでシーンごとに上書き可)。9分割グリッド:各シーンでレイアウトパックの9つのカメラ位置を俯瞰図を参照に一枚の3×3グリッドとして生成し、9枚に分割して登録。各ショットは白モデルのカメラに最も合う枠を自動選択し、適合する枠がない場合(方位/俯仰/距離/高さが範囲外)は俯瞰図+グリッド全体を参照にそのショット自身のカメラで1枚自動補完する。",
"本场景分镜背景图的参考来源;默认跟随项目输出设置「背景图模式」,可单独覆盖": "このシーンのショットプレートの参照元。既定ではプロジェクト出力設定「背景プレートモード」に従い、ここで個別に上書きできます",
