"前段交代人物与处境,中段把矛盾推到顶点,末尾留一个悬念带出下一集": "前半でキャラクターと状況を提示し、中盤で葛藤を頂点まで押し上げ、最後に次話へつながる引きを残す",
"常规剧情片、正剧、长篇小说改编、需要观众先建立情感投入的故事": "一般的なドラマ、シリアス劇、長編小説の映像化、まず感情移入させたい物語",
"冲突 → 好奇 → 补背景 → 更大冲突": "葛藤 → 興味 → 背景説明 → より大きな葛藤",
"开场直接进入冲突,先让观众想知道「为什么」,再用最少篇幅补背景,收在更大的冲突上": "冒頭からいきなり葛藤に入り、まず「なぜ」と思わせてから最小限の尺で背景を補い、より大きな葛藤で締める",
"竖屏微短剧、网文改编、强情节爽剧、需要前 10 秒留人的平台": "縦型ショートドラマ、ウェブ小説の映像化、強い展開の爽快劇、最初の 10 秒で離脱を防ぐ必要があるプラットフォーム",
"小危机 → 小高潮 → 更大危机 → 小高潮 → …… → 总爆发": "小さな危機 → 小クライマックス → より大きな危機 → 小クライマックス → …… → 大爆発",
"每个小高潮直接引出下一个更大的危机,不设平台期,张力单向爬升(费希特曲线)": "小クライマックスごとに次のより大きな危機へ直結させ、踊り場を作らず緊張を一方向に上げ続ける(フィヒテ曲線)",
"悬疑、惊悚、追逐、逃生、灾难类": "サスペンス、スリラー、追跡、脱出、災害もの",
"起 → 承 → 转 → 合": "起 → 承 → 転 → 結",
"靠「转」带来的视角反差而不是对抗来推进;不需要反派,情绪落点在「合」的领悟": "対立ではなく「転」がもたらす視点の落差で進める。悪役は不要で、感情の着地は「結」での気づき",
"日常、治愈、文艺、寓言、没有反派的人物小品": "日常、癒やし、文芸、寓話、悪役のいない人物スケッチ",
"压抑 → 小爽 → 更憋屈 → 大爽": "抑圧 → 小さな爽快 → さらに鬱屈 → 大きな爽快",
"先把观众的气憋起来,爽点隔一段给一次、越攒越大;单集内至少释放一次,集末仍留一口气": "まず観客の鬱憤をため、爽快ポイントは間隔を置いて徐々に大きく与える。1 話で最低 1 回は解放し、話の終わりにはまだ一息残す",
"逆袭、打脸、复仇、职场翻盘、爽剧": "逆転成り上がり、ざまぁ、復讐、職場での巻き返し、爽快劇",
"3 秒钩子 → 15 秒内冲突/反转 → 中段推进 → 末 10 秒卡点": "3 秒フック → 15 秒以内に葛藤/どんでん返し → 中盤で前進 → 最後の 10 秒で引き",
"按秒表切节拍:开场画面即冲突或反常,中段只推进不解释,结尾必须停在最悬的一帧上": "ストップウォッチでビートを刻む:冒頭の画がすでに葛藤か異常、中盤は説明せず前進のみ、結末は最も気になる 1 フレームで止める",
"1 分钟以内的竖屏单集、信息流投放素材、切片引流": "1 分以内の縦型単話、フィード広告素材、切り抜きでの集客",
"抛谜 → 线索 → 误导 → 揭示 → 新谜": "謎の提示 → 手がかり → ミスリード → 解明 → 新たな謎",
"每集回答一个问题再抛出一个新问题;误导必须公平,揭示之后回看要成立": "各話で 1 つの問いに答え、新たな問いを 1 つ投げる。ミスリードはフェアに、解明後に見返しても成立すること",
"推理、悬疑、烧脑反转、解谜向": "推理、サスペンス、頭を使うどんでん返し、謎解きもの",
"低强度日常 → 细节铺陈 → 单点情绪爆发 → 余韵": "低強度の日常 → 細部の積み重ね → 一点での感情の爆発 → 余韻",
"几乎不设钩子,靠细节堆叠积蓄情绪,只在一处集中释放,结尾留白": "フックはほとんど置かず、細部の積み重ねで感情をため、1 か所だけで解放し、結末は余白を残す",
"纪录片、情感、群像、家庭、年代剧": "ドキュメンタリー、感情もの、群像、家族、時代劇",
"A 线铺垫 → B 线冲突 → A 线升级 → 两线汇合": "A 線の布石 → B 線の葛藤 → A 線の加速 → 二本の線が合流",
"两条线交替推进、互相借力,在汇合点产生一加一大于二的冲击": "2 本の線を交互に進めて互いに力を借り、合流点で 1+1 が 2 を超える衝撃を生む",
"双主角、多时空、平行剪辑、群戏": "ダブル主人公、複数の時空、パラレル編集、群像劇",
"开场画面/状态 → 变化 → 回到开场画面": "冒頭の画/状態 → 変化 → 冒頭の画に戻る",
"结尾回到开头的画面或状态,但人物或意义已经不同;首尾呼应本身就是主题": "結末で冒頭の画や状態に戻るが、人物や意味はすでに違う。その呼応そのものが主題になる",
"寓言、诗意短片、概念片、单集微电影": "寓話、詩的なショート、コンセプト作品、単話の短編映画",
"正常铺垫 → 预期的高潮被抽走 → 留白": "通常の布石 → 期待されたクライマックスを外す → 余白",
"先按常规节奏建立预期,在高潮点故意落空,让观众自己补完": "まず通常のテンポで期待を作り、クライマックスであえて空振りさせ、観客自身に補完させる",
"文艺片、黑色幽默、荒诞、作者向短片": "文芸作品、ブラックユーモア、不条理、作家性の強いショート",
"建立情境与预期 → 强化预期 → 意外转折 → 笑点释放 → 回扣或新包袱": "状況と期待の設定 → 期待の強化 → 意外な転換 → 笑いの解放 → 回収または新しい仕込み",
"先把观众带进「以为会这样」,再用意外拆掉预期;每个包袱释放后要么回扣前面,要么立刻铺下一个": "まず観客を「こうなるはず」に誘い込み、意外性で期待を崩す。笑いを一つ出したら、前を回収するか、すぐ次を仕込む",
