"一集一个完整故事,人物与世界观贯穿,剧情不跨集": "1 話に 1 つの完結した物語。人物と世界観は通しで、筋は話をまたがない",
"单元故事集、动画短片集、科普/纪录系列": "オムニバス、アニメ短編集、科学解説/ドキュメンタリーシリーズ",
