"前段高密度留人 → 中段拉长副线 → 末段集中回收": "前半は高密度で離脱防止 → 中盤は副線で引き延ばす → 終盤で集中回収",
"开头约一成集数是留人窗口,密度最高;中段用副线与感情线拉长;末段集中回收伏笔": "冒頭の約 1 割の話数が離脱防止の窓口で密度が最も高い。中盤は副線と恋愛線で引き延ばし、終盤で伏線を集中回収する",
