"分镜剪辑,三个模块:① 删段——选中的时间段直接删除,剩余拼成新版本;② 换段——切掉的时间段用本组另一版本同段替代;③ 派单剪辑师——输入指令发给剪辑师工位,产物登记为新版本": "ショット編集の 3 モジュール:① 削除 — 選択区間を削除し残りで新バージョン;② 差し替え — 切った区間を同グループ別バージョンの同区間に;③ 編集者へ依頼 — 指示を編集エージェントへ送り、成果物を新バージョンとして登録",
