"0–51,越小画质越高体积越大;18 ≈ 视觉无损": "0–51。小さいほど高画質で大容量。18 ≈ 視覚的ロスレス",
"编码预设": "エンコードプリセット",
"slow(默认)": "slow(デフォルト)",
"内置非 AI 插值放大:ffmpeg scale 滤镜 + libx264 重编码,音轨流拷贝,fps/时长/画幅不变。不生成新细节,只是像素变多;不花生成费,适合只需过发布规格的项目。目标尺寸由「输出设置」成片分辨率 × 画幅自动换算。": "内蔵の非 AI 補間拡大:ffmpeg scale フィルター + libx264 再エンコード、音声はストリームコピー、fps/長さ/画角は不変。新しいディテールは生成せずピクセルが増えるだけ。生成コスト不要で、公開仕様を満たすだけでよいプロジェクト向け。目標サイズは「出力設定」の納品解像度 × 画角から自動算出。",
"Seedance 2.5 样片(Draft)模式:选中即激活,无需另填 Key 或模型,凭证与模型沿用视频生成的火山引擎标签页。": "Seedance 2.5 ドラフトモード:このタブを選ぶだけで有効。Key やモデルの追加入力は不要で、動画生成の Volcano Engine タブの資格情報とモデルを使います。",
"激活条件:视频生效渠道为火山引擎(或 BytePlus,方舟同一 API)且模型为 Seedance 2.5;项目「输出设置」草稿分辨率 = 480p、成片分辨率 = 1080p(官方:样片仅 480p,出原片仅 1080p)。不满足时视频照常按普通模式生成,并在日志提示。": "有効条件:動画の有効プロバイダーが Volcano Engine(または同じ Ark API の BytePlus)でモデルが Seedance 2.5、かつプロジェクトの「出力設定」でドラフト解像度 480p・納品解像度 1080p(公式:ドラフトは 480p のみ、本編は 1080p のみ)。満たさない場合は通常モードで生成し、ログに表示します。",
"工作方式:① 生成阶段自动带 draft=true 出 480p 样片(token 用量与普通 480p 一致),Draft 任务 ID 写进组 clip 同名 meta.json 的 draft_task 段;② 超分阶段 genmedia.py upscale 按该 ID 让方舟复用同一提示词/素材/时长/画幅/seed/音频设置生成 1080p 原片(正常推理计费),画面关键要素与过审样片一致;③ Draft 任务 ID 自创建起 7 天有效,过期只能重出样片。": "仕組み:① 生成時に draft=true を付けて 480p ドラフトを出力(トークン消費は通常の 480p と同じ)し、Draft タスク ID をグループクリップの meta.json の draft_task に記録;② アップスケール時に genmedia.py upscale がその ID で Ark に同じプロンプト/素材/長さ/画角/seed/音声設定を再利用させて 1080p 本編を生成(通常の推論課金)、主要要素は承認済みドラフトと一致;③ Draft タスク ID は作成から 7 日間有効、期限切れ後はドラフトの再生成が必要。",
"适用条件(源 clip 必须是 MiniMax-H3 768P 直出规格):含音轨;24 fps;宽高均能被 32 整除;面积 ≤ 768×1344;107–362 帧(约 4–15 秒)。": "適用条件(元クリップは MiniMax-H3 768P の直接出力であること):音声トラックあり、24 fps、幅・高さとも 32 で割り切れる、面積 ≤ 768×1344、107–362 フレーム(約 4–15 秒)。",
"云端超分工作流": "クラウドのアップスケールワークフロー",
"超分工作流 API": "アップスケールワークフロー API",
"创建(需 Comfy Cloud 订阅,与网页版共用月度额度,免费档无 API 权限);工作流下拉与本地一致(comfy/scale-* 模板;SeedVR2 节点 ComfyUI 官方内置,云端可用);长片 1080p 以上在云端可能显存不足,以任务结果为准": "で作成(Comfy Cloud のサブスクリプションが必要、Web 版と月間クレジット共有、無料枠に API 権限なし)。ワークフロー一覧はローカルと同じ(comfy/scale-* テンプレート。SeedVR2 ノードは ComfyUI 公式内蔵でクラウドでも利用可)。1080p 以上の長尺はクラウドで VRAM 不足になる場合あり、タスク結果で判断",
"获取;请先在工作区跑通 SeedVR2 类超分工作流,再把工作流 ID 或页面链接粘贴到「添加工作流」验证;无占位符的普通导出件系统会直绑唯一的源视频加载节点(LoadVideo 系)+ SeedVR2Preprocess 上游的缩放节点(目标边长/宽高)+ 采样器种子,也兼容 VIDEO/WIDTH/HEIGHT/SEED 占位符;这里的工作流收藏与视频生成板块各自独立;国内站与国际站账号与 Key 不互通": "で取得。まずワークスペースで SeedVR2 系のアップスケールワークフローを動かし、ワークフロー ID またはページ URL を「ワークフローを追加」に貼って検証。プレースホルダーのない通常のエクスポートは、唯一の元動画読み込みノード(LoadVideo 系)+ SeedVR2Preprocess 上流のリサイズノード(目標辺長/幅高)+ サンプラーのシードを自動バインド。VIDEO/WIDTH/HEIGHT/SEED プレースホルダーにも対応。ここのお気に入りは動画生成カードとは独立。.cn と .ai のアカウント・Key は共有不可",
