"NSFW 模式": "NSFW モード",
"NSFW 模式:默认关;开启后可为语言/图像/视频分别指定备用模型,标记 NSFW 的工单与分镜组自动改走备用模型,主渠道内容审核拒收时自动切换重提一次": "NSFW モード:既定はオフ。オンにすると言語/画像/動画それぞれに予備モデルを指定でき、NSFW とマークされたチケットとグループは自動的に予備モデルへ切り替わり、主チャネルがコンテンツ審査で拒否した場合は自動で切り替えて一度だけ再送信します",
