"启用 NSFW 模式": "NSFW モードを有効化",
"默认关。开启后可分别指定三类「备用模型」;派单与出图/出片按三层路由决定何时改用备用模型:① 显式标记优先——工单带 nsfw: true(总制片按剧本拆解表事件 content_flags → 分镜组 nsfw 推导,或你在分镜预览组卡点 🔞 手动标记)首次派单即走备用模型;② 兜底——主渠道返回内容审核拒收时,genmedia 同一调用内改备用渠道重提一次(不计重跑次数)并把该组记为 NSFW,后续不再先撞主模型;语言模型被拒不做进程内切换,同一 task_id 重派时改用备用语言模型。本模式只决定用哪套模型,不放宽内容安全审核与平台分级。": "既定はオフ。オンにすると 3 種類の「予備モデル」をそれぞれ指定でき、派遣と画像/動画生成は 3 段階のルーティングでいつ予備モデルへ切り替えるかを決めます:① 明示マーク優先——nsfw: true を持つチケット(プロデューサーが脚本分解表のイベント content_flags → グループ nsfw を推定、またはストーリーボードプレビューのグループカードで 🔞 を押して手動マーク)は初回派遣から予備モデルで実行;② フォールバック——主チャネルがコンテンツ審査拒否を返した場合、genmedia は同一呼び出し内で予備チャネルへ切り替えて一度だけ再送信し(再実行回数には数えない)、そのグループを NSFW として記録、以降は主モデルに先に当たりません;言語モデルの拒否はプロセス内で切り替えず、同じ task_id の再派遣時に予備言語モデルを使います。本モードはどのモデル群を使うかを決めるだけで、コンテンツ安全審査やプラットフォームのレーティングを緩めるものではありません。",
